module TopModule (
    input  clk,
    input  reset,
    output reg [4:0] q
);

    // Taps at positions 5 and 3 (assuming 1-based indexing)
    // In 0-based indexing, these are positions 4 and 2

    always @(posedge clk) begin
        if (reset) begin
            q <= 5'b10000; // active-high reset to 1
        end else begin
            // Compute next state based on Galois LFSR with taps at positions 4 and 2
            reg next_q;
            next_q = q[4] ^ q[2]; // XOR of tap positions

            // Shift right and insert next_q at the LSB
            q <= {q[3:0], next_q};
        end
    end

endmodule

