module TopModule (
    input  logic [99:0] in,
    output logic [99:0] out_both,
    output logic [99:0] out_any,
    output logic [99:0] out_different
);

    // Compute out_both: both current and previous bit are 1
    always_comb begin
        out_both[99] = 1'b0; // no previous bit for in[99]
        for (int i = 98; i >= 0; i--) begin
            out_both[i] = (in[i] && in[i+1]);
        end
    end

    // Compute out_any: current or next bit is 1
    always_comb begin
        out_any[0] = 1'b0; // no next bit for in[0]
        for (int i = 1; i <= 99; i++) begin
            out_any[i-1] = (in[i-1] || in[i]);
        end
    end

    // Compute out_different: current bit is different from previous bit (wrapping around)
    always_comb begin
        out_different[99] = (in[99] != in[0]);
        for (int i = 98; i >= 0; i--) begin
            out_different[i] = (in[i] != in[i+1]);
        end
    end

endmodule

