module TopModule (
    input  c,
    input  d,
    output reg [3:0] mux_in
);

    // Implement the K-map using a 4-to-1 MUX with a and b as selectors
    // K-map:
    // ab
    // cd  00  01  11  10
    // 00 | 0 | 0 | 0 | 1 |
    // 01 | 1 | 0 | 0 | 0 |
    // 11 | 1 | 0 | 1 | 1 |
    // 10 | 1 | 0 | 0 | 1 |

    // Determine the value of each MUX input based on c and d
    // mux_in[0] = ab=00: c=0, d=0 => 0
    // mux_in[1] = ab=01: c=0, d=1 => 1
    // mux_in[2] = ab=11: c=1, d=1 => 1
    // mux_in[3] = ab=10: c=1, d=0 => 1

    // So:
    // mux_in[0] = ~c & ~d
    // mux_in[1] = ~c & d
    // mux_in[2] = c & d
    // mux_in[3] = c & ~d

    always @(*) begin
        mux_in[0] = (~c) & (~d);
        mux_in[1] = (~c) & (d);
        mux_in[2] = (c) & (d);
        mux_in[3] = (c) & (~d);
    end

endmodule

