module TopModule (
    input  clk,
    input  reset,
    output q
);

    // Define the 5-bit register for the LFSR
    reg [4:0] lfsr;

    // Output the least significant bit as q
    assign q = lfsr[0];

    // LFSR logic
    always @(posedge clk) begin
        if (reset) begin
            // On reset, set the LFSR to 1 (active-high reset)
            lfsr <= 5'b00001;
        end else begin
            // Shift right, with taps at positions 5 and 3 (bit indices 4 and 2)
            // Tap at position 5 (bit 4) XOR q[0] is the new bit 4
            // Tap at position 3 (bit 2) XOR q[0] is the new bit 2
            // The rest shift right
            lfsr <= { lfsr[3:0], (lfsr[4] ^ lfsr[0]) ^ (lfsr[2] ^ lfsr[0]) };
        end
    end

endmodule

