module TopModule (
    input  logic [99:0] in,
    output logic [99:0] out_both,
    output logic [99:0] out_any,
    output logic [99:0] out_different
);

    // Compute out_both: both current and previous bit are 1
    always_comb begin
        out_both[99] = 1'b0; // no previous bit for in[99]
        for (int i = 98; i >= 0; i--) begin
            out_both[i] = (in[i] && in[i+1]);
        end
    end

    // Compute out_any: current or next bit is 1
    always_comb begin
        out_any[0] = 1'b0; // no next bit for in[0]
        for (int i = 1; i <= 99; i++) begin
            out_any[i-1] = (in[i-1] || in[i]);
        end
    end

    // Compute out_different: current bit is different from previous bit (wrapping around)
    always_comb begin
        out_different[99] = (in[99] != in[0]);
        for (int i = 98; i >= 0; i--) begin
            out_different[i] = (in[i] != in[i+1]);
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    output reg [4:0] q
);

    // Define the 5-bit register for the LFSR
    reg [4:0] lfsr;

    // Output the least significant bit as q
    assign q = lfsr;

    // LFSR logic
    always @(posedge clk) begin
        if (reset) begin
            // On reset, set the LFSR to 1 (active-high reset)
            lfsr <= 5'b00001;
        end else begin
            // Shift right, with taps at positions 5 and 3 (bit indices 4 and 2)
            // Tap at position 5 (bit 4) XOR q[0] is the new bit 4
            // Tap at position 3 (bit 2) XOR q[0] is the new bit 2
            // The rest shift right
            lfsr <= { lfsr[3:0], (lfsr[4] ^ lfsr[0]) ^ (lfsr[2] ^ lfsr[0]) };
        end
    end

endmodule

