module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);

    // State definition
    typedef enum reg [2:0] {
        S_SEARCH,      // Searching for 1101
        S_RECEIVE,     // Receiving 1101
        S_DELAY,       // Receiving delay bits
        S_COUNTING,    // Counting down
        S_WAIT_ACK     // Waiting for ack
    } state_t;

    state_t state, next_state;

    // Delay bits storage
    reg [3:0] delay;

    // Counting variables
    reg [11:0] count_timer;
    reg [11:0] count_remaining;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S_SEARCH;
            count <= 4'b0000;
            counting <= 1'b0;
            done <= 1'b0;
            count_timer <= 12'd0;
            count_remaining <= 12'd0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(posedge clk) begin
        next_state = state;

        case (state)
            S_SEARCH: begin
                if (data == 4'b1101) begin
                    next_state = S_RECEIVE;
                end
            end

            S_RECEIVE: begin
                // Wait for 4 bits to be received
                if (data == 4'b1101) begin
                    next_state = S_DELAY;
                end
            end

            S_DELAY: begin
                // Shift in 4 bits for delay
                if (data == 4'b1101) begin
                    next_state = S_COUNTING;
                end
            end

            S_COUNTING: begin
                // Count for (delay + 1) * 1000 cycles
                if (count_timer == 12'd0) begin
                    next_state = S_WAIT_ACK;
                end else begin
                    next_state = S_COUNTING;
                end
            end

            S_WAIT_ACK: begin
                if (ack) begin
                    next_state = S_SEARCH;
                end
            end
        endcase
    end

    // Data input shift register for pattern detection
    reg [3:0] shift_reg;

    always @(posedge clk) begin
        if (state == S_SEARCH || state == S_RECEIVE || state == S_DELAY) begin
            shift_reg <= {shift_reg[2:0], data};
        end
    end

    // Delay bit capture
    always @(posedge clk) begin
        if (state == S_DELAY) begin
            delay <= {shift_reg[3], shift_reg[2], shift_reg[1], shift_reg[0]};
        end
    end

    // Counting logic
    always @(posedge clk) begin
        if (state == S_COUNTING) begin
            count_timer <= count_timer - 1;
            count_remaining <= count_remaining - 1;
            count <= count_remaining[3:0];
            counting <= 1'b1;
        end else begin
            counting <= 1'b0;
        end
    end

    // Done signal
    always @(posedge clk) begin
        if (state == S_COUNTING && count_timer == 12'd0) begin
            done <= 1'b1;
        end else begin
            done <= 1'b0;
        end
    end

endmodule

