            S_SEARCH: begin
                if (shift_count == 4) begin
                    if (shift_reg == 4'b1101) begin
                        next_state = S_MATCH;
                    end else begin
                        next_state = S_IDLE;
                        shift_reg <= 4'b0000;
                        shift_count <= 4'b0000;
                    end
                end else begin
                    shift_reg <= {shift_reg[2:0], data};
                    shift_count <= shift_count + 1;
                end
            end

            S_MATCH: begin
                next_state = S_READ_DELAY;
                shift_reg <= {shift_reg[2:0], data};
                shift_count <= shift_count + 1;
            end

            S_READ_DELAY: begin
                if (shift_count == 4) begin
                    next_state = S_COUNTING;
                    delay <= shift_reg;
                    remaining <= delay;
                    current_count <= 4'b0000;
                end else begin
                    shift_reg <= {shift_reg[2:0], data};
                    shift_count <= shift_count + 1;
                end
            end

            S_COUNTING: begin
                if (remaining > 0) begin
                    next_state = S_COUNTING;
                    current_count <= current_count + 1;
                    if (current_count == 1000) begin
                        remaining <= remaining - 1;
                        current_count <= 4'b0000;
