        if (reset) begin
            count <= 4'b0000;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            if (state == S_COUNTING) begin
                count <= current_count;
                counting <= 1'b1;
            end else begin
                count <= 4'b0000;
                counting <= 1'b0;
            end
        end
    end

