module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);

    // State definition
    typedef enum reg [2:0] {
        S_SEARCH,      // Searching for 1101
        S_RECEIVE,     // Receiving 1101
        S_DELAY,       // Receiving delay bits
        S_COUNTING,    // Counting down
        S_WAIT_ACK     // Waiting for ack
    } state_t;

    state_t state, next_state;

    // Delay bits storage
    reg [3:0] delay;

    // Count down counter
    reg [11:0] counter;

    // Current remaining time
    reg [3:0] remaining_time;

    // State machine logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S_SEARCH;
            delay <= 4'b0000;
            counter <= 12'd0;
            remaining_time <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            S_SEARCH: begin
                if (data == 4'b1101) begin
                    next_state = S_RECEIVE;
                end
            end

            S_RECEIVE: begin
                // Check if we have received 1101
                if (data == 4'b1101) begin
                    next_state = S_DELAY;
                end
            end

            S_DELAY: begin
                // Shift in 4 bits for delay
                if (data == 4'b1101) begin
                    next_state = S_RECEIVE;
                end else if (delay == 4'b1111) begin
                    next_state = S_COUNTING;
                end else begin
                    delay <= {delay[2:0], data};
                end
            end

            S_COUNTING: begin
                if (counter == 12'd0) begin
                    next_state = S_WAIT_ACK;
                end else begin
                    next_state = S_COUNTING;
                end
            end

            S_WAIT_ACK: begin
                if (ack) begin
                    next_state = S_SEARCH;
                end
            end
        endcase
    end

    // Output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                S_SEARCH, S_RECEIVE, S_DELAY: begin
                    count <= 4'd0;
                    counting <= 1'b0;
                    done <= 1'b0;
                end

                S_COUNTING: begin
                    if (counter > 12'd0) begin
                        counter <= counter - 12'd1;
                        remaining_time <= (counter / 12'd1000) % 4'd10;
                        count <= remaining_time;
                        counting <= 1'b1;
                    end else begin
                        done <= 1'b1;
                        counting <= 1'b0;
                    end
                end

                S_WAIT_ACK: begin
                    count <= 4'd0;
                    counting <= 1'b0;
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

